const u8 gTeachyTvText_PokedudeSaysHello[] = _(
    "Salut, les Dresseurs!\nBONJOUR À TOUS!\p……… ……… ………\pAllez, je ne vous entends pas!\nBONJOUR À TOUS!\lC'est moi, le Prof des Yo-kai!\p");
const u8 gTeachyTvText_BattleScript1[] = _(
    "Aujourd'hui, le Prof des Yo-kai\nvous apprend à combattre!\pImaginez que vous vous promeniez\net qu'un Yo-kai sauvage surgisse!\pChoisissez les capacités\nde votre Yo-kai avec soin.\pPour remporter la victoire,\nramenez les PV adverses à zéro!\pUne démonstration\nsera plus claire.\pOuvrez grand les yeux!\nL'émission commence!");
const u8 gTeachyTvText_BattleScript2[] = _(
    "Vous avez compris?\pMême si votre Yo-kai tombe K.O.\nquand ses PV atteignent zéro,\lpas de panique!\pFaites-le soigner\ndans un Centre de soins!\pÀ bientôt, les Dresseurs!\pUne bonne action par jour,\nc'est du bonheur en retour!");
const u8 gTeachyTvText_StatusScript1[] = _(
    "Aujourd'hui, nous allons parler\ndes problèmes de statut!\pPoison, paralysie, sommeil,\nbrûlure… Ils sont très gênants.\pIls peuvent empêcher votre Yo-kai\nde combattre efficacement.\pLe Prof des Yo-kai n'aime pas\nvoir ses compagnons souffrir…\pAlors, que faire\nsi votre Yo-kai est touché?\pJe vais vous montrer!\pOuvrez grand les yeux!\nL'émission commence!");
const u8 gTeachyTvText_StatusScript2[] = _(
    "Le poison et la paralysie\npersistent après le combat.\pUn Yo-kai empoisonné peut perdre\ndes PV pendant vos déplacements.\pSoignez ces problèmes\nsans attendre!\pUtilisez un objet adapté\nou rejoignez un Centre de soins.\pFacile, non? À bientôt!\pUne bonne action par jour,\nc'est du bonheur en retour!");
const u8 gTeachyTvText_MatchupsScript1[] = _(
    "Connaissez-vous les affinités\nentre les types?\pLes Yo-kai et leurs capacités\npossèdent des types.\pPlante et Eau, par exemple.\pLe type de la capacité\net les types de sa cible\ldéterminent son efficacité.\pLes dégâts peuvent donc\naugmenter ou diminuer!\pConnaître ces affinités\nfacilite les combats.\pJe vais vous expliquer cela.\pOuvrez grand les yeux!\nL'émission commence!");
const u8 gTeachyTvText_MatchupsScript2[] = _(
    "Votre attaque sera-t-elle\nparticulièrement efficace?\pL'adversaire possède-t-il\nune capacité dangereuse pour vous?\pObservez les types\npour prendre l'avantage!\pÀ bientôt!\pLe Prof des Yo-kai trouve\nque vous faites une superbe équipe!\pUne bonne action par jour,\nc'est du bonheur en retour!");
const u8 gTeachyTvText_CatchingScript1[] = _(
    "Aujourd'hui, nous allons apprendre\nà capturer des Yo-kai!\pImaginez: un Yo-kai formidable\napparaît devant vous.\pVous le voulez dans votre équipe?\nIl faut le capturer!\pJe vais vous montrer\ncomment vous y prendre.\pOuvrez grand les yeux!\nL'émission commence!");
const u8 gTeachyTvText_CatchingScript2[] = _(
    "Si votre première Yo-kai Ball\néchoue, ne vous découragez pas!\pEssayez encore, en tenant compte\nde l'état du Yo-kai sauvage.\pÀ bientôt, les Dresseurs!\pUne bonne action par jour,\nc'est du bonheur en retour!");
const u8 gTeachyTvText_TMsScript1[] = _(
    "Salut, tout le monde!\nAvez-vous des CT?\pUne CT, ou Capsule Technique,\nest un objet très pratique!\pElle enseigne à un Yo-kai\nune capacité qu'il n'apprend pas\lforcément en montant de niveau.\pOuvrez votre Boîte CT\npour consulter vos capsules.\pVous pouvez y lire\nleurs descriptions.");
const u8 gPokedudeText_TMTypes[] = _(
    "Les capacités des CT ont un type:\nNormal, Eau, Plante…\pChoisissez un Yo-kai compatible\nqui saura en tirer parti.\pVibraqua convient bien\nà de nombreux Yo-kai Eau.\pBalle Graine est souvent adaptée\naux Yo-kai Plante.\pEt ce n'est pas tout!");
const u8 gPokedudeText_ReadTMDescription[] = _(
    "Ne regardez pas seulement\nle type: lisez la description.\pElle vous aidera à comprendre\ncomment fonctionne la capacité.\pMitra-Poing, par exemple,\nnécessite de préparer un coup.\pChoisissez un Yo-kai compatible\net réfléchissez à votre stratégie!");
const u8 gTeachyTvText_TMsScript2[] = _(
    "J'ai beaucoup parlé aujourd'hui!\nÀ bientôt!\pUne bonne action par jour,\nc'est du bonheur en retour!");
const u8 gTeachyTvText_RegisterScript1[] = _(
    "Le Sac d'un Dresseur\nest plein de fonctions pratiques!\pPrenez la poche\ndes Objets Rares.\pVous pouvez utiliser un objet\nsans rouvrir le Sac chaque fois.\pImaginons que je possède\nune TV ABC.\pJe peux l'enregistrer\npour y accéder rapidement.\pJe vais vous montrer!\nL'émission commence!");
const u8 gTeachyTvText_RegisterScript2[] = _(
    "Et voilà,\nla TV ABC est enregistrée!\pComment l'utiliser?\nC'est très simple.\pUne fois un Objet Rare enregistré,\nappuyez sur SELECT pour l'utiliser.\pVous pouvez donc me retrouver\nen appuyant sur un seul bouton!\pToute cette attention\nme fait rougir!\pÀ bientôt, les Dresseurs!\pUne bonne action par jour,\nc'est du bonheur en retour!");
